// Deploy script for darcy-chat edge function
// Reads all local files and calls Supabase Management API

const fs = require('fs');
const path = require('path');

const PROJECT_REF = 'bzkkonblfmdoqbumpsmo';
const FUNCTION_SLUG = 'darcy-chat';
const BASE_DIR = path.join(__dirname, 'supabase', 'functions', 'darcy-chat');

// Files to deploy
const FILES = [
    'index.ts',
    'config.ts',
    'utils/helpers.ts',
    'services/mcp.ts',
    'services/moodle-course.ts',
    'services/openrouter.ts',
    'services/learning.ts',
    'services/prompts.ts',
    'services/prefetch.ts',
    'services/tools.ts',
];

async function getAccessToken() {
    // Try to get from environment
    const token = process.env.SUPABASE_ACCESS_TOKEN;
    if (token) return token;

    // Try common config locations
    const locations = [
        path.join(process.env.USERPROFILE || '', '.supabase', 'access-token'),
        path.join(process.env.APPDATA || '', 'supabase', 'access-token'),
        path.join(process.env.HOME || '', '.supabase', 'access-token'),
    ];

    for (const loc of locations) {
        try {
            return fs.readFileSync(loc, 'utf8').trim();
        } catch { }
    }

    throw new Error('No Supabase access token found. Set SUPABASE_ACCESS_TOKEN env var or run: npx supabase login');
}

async function deploy() {
    const accessToken = await getAccessToken();

    // Read all files
    const files = FILES.map(f => ({
        name: f,
        content: fs.readFileSync(path.join(BASE_DIR, f), 'utf8')
    }));

    console.log('Deploying ' + files.length + ' files to ' + FUNCTION_SLUG + '...');
    files.forEach(f => console.log('  - ' + f.name + ' (' + Math.round(f.content.length / 1024) + 'KB)'));

    const body = JSON.stringify({
        slug: FUNCTION_SLUG,
        name: FUNCTION_SLUG,
        entrypoint_path: 'index.ts',
        import_map: false,
        verify_jwt: false, // alinhado ao supabase/config.toml (widget chama sem JWT)
        files: files
    });

    const res = await fetch(
        'https://api.supabase.com/v1/projects/' + PROJECT_REF + '/functions/' + FUNCTION_SLUG,
        {
            method: 'PATCH',
            headers: {
                'Authorization': 'Bearer ' + accessToken,
                'Content-Type': 'application/json'
            },
            body: body
        }
    );

    if (!res.ok) {
        const text = await res.text();
        console.error('Deploy failed (' + res.status + '): ' + text);

        // Try POST (create) if PATCH (update) fails
        if (res.status === 404) {
            console.log('Function not found, trying to create...');
            const createRes = await fetch(
                'https://api.supabase.com/v1/projects/' + PROJECT_REF + '/functions',
                {
                    method: 'POST',
                    headers: {
                        'Authorization': 'Bearer ' + accessToken,
                        'Content-Type': 'application/json'
                    },
                    body: body
                }
            );
            if (!createRes.ok) {
                console.error('Create also failed: ' + (await createRes.text()));
            } else {
                console.log('Function created successfully!');
            }
        }
    } else {
        console.log('Deploy successful!');
        const data = await res.json();
        console.log(JSON.stringify(data, null, 2));
    }
}

deploy().catch(err => {
    console.error('Error:', err.message);
    process.exit(1);
});

