// dashboardApi.ts
// Cliente do dashboard para a Edge Function autenticada `dashboard-api` (US-018).
//
// POR QUE: apos o lockdown de RLS (US-002), as tabelas de PII/analytics ficam
// deny-anon — a leitura direta via PostgREST com a anon key (supabase.from(...))
// para de funcionar. Toda leitura do dashboard passa a ir por AQUI: a function
// valida o access_token do Supabase Auth (Authorization: Bearer <jwt>) + checa a
// allowlist de e-mails e le com service_role (ver supabase/functions/dashboard-api).
//
// CONTRATO da function (POST /functions/v1/dashboard-api):
//   body: { resource, columns?, filters?, order?, limit? }
//   resposta: { data: [...] }  (200)  |  { error: ... }  (4xx/5xx)
//   filtros suportados: eq | neq | gte | lte | in | not_null | or
// O token e obtido de supabase.auth.getSession() (a sessao do login da US-017).

import { supabase } from "@/integrations/supabase/client";

// Mesma URL do projeto Supabase usada pelo client (client.ts e auto-gerado e nao
// exporta a URL, entao mantemos a constante aqui em sincronia com ela).
const SUPABASE_URL = "https://bzkkonblfmdoqbumpsmo.supabase.co";
const DASHBOARD_API_URL = `${SUPABASE_URL}/functions/v1/dashboard-api`;

// Recursos expostos pela function (allowlist espelhada do index.ts da function).
export type DashboardResource =
  | "users"
  | "analytics_sessions_detailed"
  | "analytics_interactions"
  | "analytics_feedback_detailed"
  | "analytics_question_frequency"
  | "analytics_abandonment_points"
  | "chat_sessions"
  | "messages"
  | "v_active_widgets"
  | "analytics_data_consent"
  | "analytics_data_access_logs"
  | "telemetry_turns"
  | "v_telemetry_health";

// Operadores de filtro suportados (replicam os que os hooks usam hoje).
export type DashboardFilter =
  | { op: "eq" | "neq" | "gte" | "lte"; column: string; value: string | number | boolean }
  | { op: "in"; column: string; value: Array<string | number> }
  | { op: "not_null"; column: string }
  | { op: "or"; expr: string };

export interface DashboardQuery {
  resource: DashboardResource;
  columns?: string[];
  filters?: DashboardFilter[];
  order?: { column: string; ascending?: boolean };
  limit?: number;
}

/**
 * Executa uma leitura via dashboard-api e retorna as linhas (data) tipadas como T[].
 *
 * - Pega o access_token da sessao atual (supabase.auth.getSession()).
 * - Sem sessao -> lanca Error('not_authenticated') (o ProtectedRoute da US-017 ja
 *   evita montar o dashboard sem sessao, mas falhamos de forma tratavel mesmo assim).
 * - Erro HTTP/JSON -> lanca Error com a mensagem da function (os hooks usam react-query,
 *   que captura o throw e popula o `error` state — preservando o comportamento atual
 *   em que `if (error) throw error` propagava o erro do PostgREST).
 */
// NOTA TS: o default e `Record<string, any>` (linha de objeto), NAO `any`. Um
// elemento `any` faz `.reduce(cb, {} as Record<string,number>)` inferir `unknown`
// (quirk do TS com arrays de `any`), quebrando as agregacoes dos hooks de analytics.
// `Record<string, any>` mantem o acesso livre a colunas e preserva a inferencia.
export async function dashboardQuery<T = Record<string, any>>(query: DashboardQuery): Promise<T[]> {
  const { data: sessionData } = await supabase.auth.getSession();
  const accessToken = sessionData?.session?.access_token;
  if (!accessToken) {
    throw new Error("not_authenticated");
  }

  let res: Response;
  try {
    res = await fetch(DASHBOARD_API_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${accessToken}`,
      },
      body: JSON.stringify(query),
    });
  } catch (e: any) {
    throw new Error(`dashboard_api_network_error: ${e?.message || e}`);
  }

  let body: any = null;
  try {
    body = await res.json();
  } catch {
    body = null;
  }

  if (!res.ok) {
    const detail = body?.error || res.statusText || `HTTP ${res.status}`;
    throw new Error(`dashboard_api_error: ${detail}`);
  }

  const rows = body?.data;
  return (Array.isArray(rows) ? rows : []) as T[];
}

