import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));

// ─── Config LOCAL/self-hosted injetada em build time ─────────────────────────────
// Carrega o .env da raiz (darcy-local/.env) se existir; process.env tem precedência.
// Assim `npm run build` no widget já pega a URL/anon key configuradas, sem wrapper.
function loadDotEnv(p) {
  if (!existsSync(p)) return;
  for (const raw of readFileSync(p, 'utf8').split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq === -1) continue;
    const key = line.slice(0, eq).trim();
    let val = line.slice(eq + 1).trim().replace(/^["']|["']$/g, '');
    if (process.env[key] === undefined) process.env[key] = val;
