# Expõe o kong local (54321) publicamente (cloudflared/ngrok). Ver tunnel.sh para detalhes.
#   $env:CF_TUNNEL_NAME="darcy"; ./scripts/tunnel.ps1     (túnel nomeado, URL fixa)
#   ./scripts/tunnel.ps1                                   (quick tunnel, URL aleatória)
param([int]$Port = 54321)
$target = "http://127.0.0.1:$Port"

if ($env:NGROK_DOMAIN) {
  if (-not (Get-Command ngrok -ErrorAction SilentlyContinue)) { Write-Error "ngrok não encontrado."; exit 1 }
  Write-Host "==> ngrok $target --domain=$($env:NGROK_DOMAIN)"
  ngrok http $Port --domain=$env:NGROK_DOMAIN
  return
}
if (-not (Get-Command cloudflared -ErrorAction SilentlyContinue)) { Write-Error "cloudflared não encontrado."; exit 1 }

if ($env:CF_TUNNEL_NAME) {
  Write-Host "==> cloudflared named tunnel '$($env:CF_TUNNEL_NAME)' -> $target"
  cloudflared tunnel run $env:CF_TUNNEL_NAME
} else {
  Write-Host "==> cloudflared QUICK tunnel -> $target (URL aleatória trycloudflare.com)"
  Write-Host "    Depois: atualize o .env com a URL, rebuild do widget e reseed."
  cloudflared tunnel --url $target
}

