// Sobe widget-src/dist/widget.js para o bucket `ativos` do Supabase LOCAL em execução.
// Use APÓS um build, para atualizar o widget sem precisar de `supabase db reset` (que
// re-semeia o bucket). O bucket já existe (semeado pelo config.toml no start/reset).
//
// Requer a service_role key local (impressa por `npx supabase status`):
//   SUPABASE_SERVICE_ROLE_KEY=... node scripts/upload-widget.mjs
//   (SUPABASE_URL default = http://127.0.0.1:54321)
import { readFileSync, existsSync } from 'fs';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const SUPABASE_URL = process.env.SUPABASE_URL || 'http://127.0.0.1:54321';
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!SERVICE_KEY) {
  console.error('ERRO: defina SUPABASE_SERVICE_ROLE_KEY (veja `npx supabase status`).');
  process.exit(1);
}

const widgetPath = resolve(__dirname, '../widget-src/dist/widget.js');
if (!existsSync(widgetPath)) {
  console.error(`ERRO: ${widgetPath} não existe. Rode o build primeiro (./scripts/build-widget.sh).`);
  process.exit(1);
}

const body = readFileSync(widgetPath);
const url = `${SUPABASE_URL}/storage/v1/object/ativos/widget.js`;
const res = await fetch(url, {
  method: 'POST',
  headers: {
    Authorization: `Bearer ${SERVICE_KEY}`,
    'x-upsert': 'true',
    'Content-Type': 'text/javascript',
  },
  body,
});

console.log(`POST ${url} -> ${res.status}`);
console.log(await res.text());
if (!res.ok) process.exit(1);
console.log('OK: widget.js atualizado no bucket `ativos`.');

