#!/usr/bin/env node
// ─────────────────────────────────────────────────────────────────────────────
// Darcy — Verificação da telemetria training-grade
//
// "Estamos capturando TUDO certo?" — este harness comprova ponta-a-ponta:
//   1. POST real no darcy-chat (endpoint ao vivo) → obtém turn_id
//   2. Lê telemetry_turns (service_role) e checa que o turno foi gravado com
//      conteúdo, modelo, tokens, custo, latência e cadeia de fallback
//   3. Imprime v_telemetry_health (completude por campo crítico, 7 dias)
//
// Uso:
//   SUPABASE_SERVICE_ROLE_KEY=eyJ... node evals/verify-telemetry.mjs
//   node evals/verify-telemetry.mjs --keep      (não apaga o turno de teste)
//   node evals/verify-telemetry.mjs --course    (testa o caminho de curso)
//
// Sem a service_role só dá pra confirmar que o turn_id voltou (verificação
// parcial). Exit 0 se tudo ok; 1 se algo essencial faltou.
// ─────────────────────────────────────────────────────────────────────────────

const SUPABASE_URL = process.env.SUPABASE_URL || "https://bzkkonblfmdoqbumpsmo.supabase.co";
// anon key é pública (embarcada no widget) — só para chamar o darcy-chat.
const ANON_KEY = process.env.SUPABASE_ANON_KEY ||
  "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImJ6a2tvbmJsZm1kb3FidW1wc21vIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NTE0ODE5NjksImV4cCI6MjA2NzA1Nzk2OX0.LOkv_T2osw9leSsom7h3NUI14M-CeR_Hk8NtR_Lcq9w";
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY || null;

const args = process.argv.slice(2);
const KEEP = args.includes("--keep");
const COURSE = args.includes("--course");

const CHAT_URL = `${SUPABASE_URL}/functions/v1/darcy-chat`;
const REST = `${SUPABASE_URL}/rest/v1`;

const C = { g: "\x1b[32m", r: "\x1b[31m", y: "\x1b[33m", d: "\x1b[2m", x: "\x1b[0m" };
const ok = (m) => console.log(`${C.g}✓${C.x} ${m}`);
const bad = (m) => console.log(`${C.r}✗${C.x} ${m}`);
const warn = (m) => console.log(`${C.y}!${C.x} ${m}`);
const dim = (m) => console.log(`${C.d}${m}${C.x}`);

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function main() {
  let failures = 0;

  // ── 1. Dispara um turno real ───────────────────────────────────────────────
  const marker = `verificacao de telemetria ${Date.now()}`;
  const message = COURSE
    ? `Pode me explicar o conteúdo desta atividade? (${marker})`
    : `Como recupero minha senha do Aprender? (${marker})`;

  console.log(`\n• POST ${CHAT_URL}`);
  dim(`  mensagem: "${message}"`);

  let resp;
  try {
    const res = await fetch(CHAT_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        apikey: ANON_KEY,
        Authorization: `Bearer ${ANON_KEY}`,
      },
      body: JSON.stringify({
        message,
        conversation: [],
        context: COURSE
          ? { type: "course", courseId: "1", userId: null, url: "https://aprender2.unb.br/course/view.php?id=1" }
          : { type: "general", url: "https://aprender2.unb.br/my/" },
        telemetry: {
          conversation_id: `verify-${Date.now()}`,
          turn_index: 0,
          session_id: crypto.randomUUID(),
          browser_id: `verify-harness`,
        },
      }),
    });
    resp = await res.json();
    if (!res.ok) { bad(`darcy-chat HTTP ${res.status}`); process.exit(1); }
  } catch (e) {
    bad(`falha ao chamar darcy-chat: ${e.message}`);
    process.exit(1);
  }

  if (resp.turn_id) ok(`darcy-chat respondeu com turn_id=${resp.turn_id}`);
  else { bad("darcy-chat NÃO devolveu turn_id — o widget não consegue ligar feedback ao turno"); failures++; }
  dim(`  modelo: ${resp.model || "?"} | resposta: ${(resp.response || "").slice(0, 70)}...`);

  // ── 2. Verifica a gravação em telemetry_turns ──────────────────────────────
  if (!SERVICE_KEY) {
    warn("SUPABASE_SERVICE_ROLE_KEY não definida — pulei a verificação no banco.");
    warn("Defina-a para comprovar que o turno foi gravado com todos os campos.");
    process.exit(failures > 0 ? 1 : 0);
  }

  const svc = {
    apikey: SERVICE_KEY,
    Authorization: `Bearer ${SERVICE_KEY}`,
    "Content-Type": "application/json",
  };

  // O turno é gravado em background — espera com retry.
  let turn = null;
  for (let i = 0; i < 6 && !turn; i++) {
    await sleep(1000);
    const r = await fetch(`${REST}/telemetry_turns?turn_id=eq.${resp.turn_id}&select=*`, { headers: svc });
    if (r.ok) { const rows = await r.json(); if (rows.length) turn = rows[0]; }
  }

  if (!turn) {
    bad("turno NÃO encontrado em telemetry_turns após 6s — a gravação em background falhou");
    process.exit(1);
  }
  ok("turno encontrado em telemetry_turns");

  // ── 3. Checa os campos que TÊM que estar lá ────────────────────────────────
  const checks = [
    ["model_used", turn.model_used, (v) => !!v],
    ["latency_ms", turn.latency_ms, (v) => v != null && v >= 0],
    ["model_chain", turn.model_chain, (v) => Array.isArray(v) && v.length > 0],
    ["schema_version", turn.schema_version, (v) => !!v],
    ["valid", turn.valid, (v) => v === true],
    ["content_captured", turn.content_captured, (v) => v === true],
    ["user_message", turn.user_message, (v) => typeof v === "string" && v.includes(marker)],
    ["assistant_message", turn.assistant_message, (v) => !!v],
    ["system_prompt", turn.system_prompt, (v) => !!v],
    ["conversation_window", turn.conversation_window, (v) => Array.isArray(v)],
    ["user_message_redacted", turn.user_message_redacted, (v) => !!v],
    ["retention_until", turn.retention_until, (v) => !!v],
  ];
  for (const [name, val, pred] of checks) {
    if (pred(val)) ok(`${name} ok ${C.d}(${JSON.stringify(val)?.slice(0, 50)})${C.x}`);
    else { bad(`${name} faltando/errado: ${JSON.stringify(val)?.slice(0, 80)}`); failures++; }
  }

  // Completude (não-fatal): tokens/custo dependem do OpenRouter devolver usage.
  if (turn.total_tokens > 0) ok(`tokens capturados (prompt=${turn.prompt_tokens} compl=${turn.completion_tokens} total=${turn.total_tokens})`);
  else warn(`total_tokens ausente/zero — OpenRouter não devolveu usage neste turno (monitorar pct_with_tokens)`);
  if (turn.cost_usd != null) ok(`cost_usd=${turn.cost_usd}`);
  else warn("cost_usd nulo");
  if (turn.quality_gate_passed != null) ok(`quality_gate_passed=${turn.quality_gate_passed} was_best_effort=${turn.was_best_effort} fallback_count=${turn.fallback_count}`);

  // ── 4. Saúde geral do dado (7 dias) ────────────────────────────────────────
  console.log("\n• v_telemetry_health (últimos 7 dias):");
  const hr = await fetch(`${REST}/v_telemetry_health?select=*`, { headers: svc });
  if (hr.ok) {
    const [h] = await hr.json();
    if (h) {
      console.table([{
        turnos: h.turns_7d, invalidos: h.invalid_turns, erros: h.error_turns,
        "%modelo": h.pct_with_model, "%tokens": h.pct_with_tokens, "%custo": h.pct_with_cost,
        "%conteudo": h.pct_with_content, "%cadeia": h.pct_with_chain, feedback_ligado: h.feedback_linked_7d,
      }]);
    }
  } else dim(`  (não consegui ler a view: HTTP ${hr.status})`);

  // ── 5. Limpa o turno de teste (a menos que --keep) ─────────────────────────
  if (!KEEP) {
    await fetch(`${REST}/telemetry_turns?turn_id=eq.${resp.turn_id}`, { method: "DELETE", headers: svc });
    dim(`\n  turno de teste apagado (use --keep para manter)`);
  }

  console.log("");
  if (failures === 0) { ok(`TELEMETRIA OK — captura ponta-a-ponta comprovada`); process.exit(0); }
  else { bad(`${failures} verificação(ões) falharam`); process.exit(1); }
}

main().catch((e) => { bad(`erro inesperado: ${e.message}`); process.exit(1); });

