if (-not $env:SUPABASE_SERVICE_ROLE_KEY) {
  Write-Host "==> tentando obter service_role key via 'supabase status'..."
  # NÃO usar 2>$null em exe nativo com ErrorActionPreference=Stop (vira NativeCommandError e
  # aborta o script). Capturamos stdout e silenciamos erro localmente.
  try {
    $status = & npx supabase status --output env 2>&1 | Where-Object { $_ -notmatch '^npm' }
    $kv = $status | Select-String -Pattern 'SERVICE_ROLE_KEY="?([^"]+)"?'
    if ($kv) { $env:SUPABASE_SERVICE_ROLE_KEY = $kv.Matches[0].Groups[1].Value }
  } catch { Write-Warning "Não consegui ler 'supabase status': $($_.Exception.Message)" }
}

