  Write-Host "==> tentando obter service_role key via 'supabase status'..."
  $line = (npx supabase status 2>$null | Select-String -Pattern "service_role key")
  if ($line) { $env:SUPABASE_SERVICE_ROLE_KEY = ($line.ToString() -split '\s+')[-1] }
}

if ($env:SUPABASE_SERVICE_ROLE_KEY) {
  Write-Host "==> upload do widget.js para o bucket ativos"
  node scripts/upload-widget.mjs
} else {
  Write-Warning "Sem SUPABASE_SERVICE_ROLE_KEY — pulei o upload. widget.js já está em supabase/seed/ativos/ (semeado no próximo db reset)."
}

