import * as esbuild from 'esbuild';
import { copyFileSync, mkdirSync, readFileSync, writeFileSync, existsSync } from 'fs';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));

// ─── Config LOCAL/self-hosted injetada em build time ─────────────────────────────
// Carrega o .env da raiz (darcy-local/.env) se existir; process.env tem precedência.
// Assim `npm run build` no widget já pega a URL/anon key configuradas, sem wrapper.
function loadDotEnv(p) {
  if (!existsSync(p)) return;
  for (const raw of readFileSync(p, 'utf8').split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq === -1) continue;
    const key = line.slice(0, eq).trim();
    let val = line.slice(eq + 1).trim().replace(/^["']|["']$/g, '');
    if (process.env[key] === undefined) process.env[key] = val;
  }
}
loadDotEnv(resolve(__dirname, '../.env'));

// Browser-facing: em produção tunelada precisa ser a URL PÚBLICA do túnel (kong/54321).
const SUPABASE_URL = process.env.SUPABASE_URL || 'http://127.0.0.1:54321';
// Anon key padrão do `supabase start` (JWT secret demo). Troque via .env se a sua diferir.
const SUPABASE_ANON_KEY = process.env.SUPABASE_ANON_KEY ||
  'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJyb2xlIjoiYW5vbiIsImlzcyI6InN1cGFiYXNlLWRlbW8iLCJpYXQiOjE2NDE3NjkyMDAsImV4cCI6MTc5OTUzNTYwMH0.dc_X5iR_VP_qT0zsiyj_I_OZ2T9FtRU2BBNWN8Bu4GE';
const WIDGET_ASSETS_URL = process.env.WIDGET_ASSETS_URL ||
  `${SUPABASE_URL}/storage/v1/object/public/widget-assets/darcy-avatar.png`;
const VOICE_ENABLED = (process.env.VOICE_ENABLED ?? 'true') !== 'false';

// Custom plugin to handle CSS as inline injection
const inlineCSSPlugin = {
  name: 'inline-css',
  setup(build) {
    // Handle .css imports - return JS that injects the CSS
    build.onLoad({ filter: /\.css$/ }, async (args) => {
      const css = readFileSync(args.path, 'utf8');
      // Escape the CSS for embedding in JS
      const escapedCSS = css
        .replace(/\\/g, '\\\\')
        .replace(/`/g, '\\`')
        .replace(/\$/g, '\\$');

      // Return JS code that injects the CSS immediately
      return {
        contents: `
                    (function() {
                        if (typeof document !== 'undefined' && !document.getElementById('darcy-widget-styles')) {
                            var style = document.createElement('style');
                            style.id = 'darcy-widget-styles';
                            style.textContent = \`${escapedCSS}\`;
                            document.head.appendChild(style);
                            console.log('[WIDGET] CSS injected');
                        }
                    })();
                    export default '';
                `,
        loader: 'js',
      };
    });
  },
};

async function build() {
  console.log('🔨 Building widget...');
  console.log(`   SUPABASE_URL = ${SUPABASE_URL}`);
  console.log(`   VOICE_ENABLED = ${VOICE_ENABLED}`);

  // Ensure dist directory exists
  mkdirSync(resolve(__dirname, 'dist'), { recursive: true });

  // Build the JS bundle with esbuild
  await esbuild.build({
    entryPoints: [resolve(__dirname, 'src/main.tsx')],
    bundle: true,
    minify: true,
    format: 'iife',
    globalName: 'DarcyWidget',
    outfile: resolve(__dirname, 'dist/widget.js'),
    jsx: 'automatic',
    jsxImportSource: 'preact',
    define: {
      'process.env.NODE_ENV': '"production"',
      __DARCY_SUPABASE_URL__: JSON.stringify(SUPABASE_URL),
      __DARCY_SUPABASE_ANON_KEY__: JSON.stringify(SUPABASE_ANON_KEY),
      __DARCY_WIDGET_ASSETS_URL__: JSON.stringify(WIDGET_ASSETS_URL),
      __DARCY_VOICE_ENABLED__: String(VOICE_ENABLED),
    },
    plugins: [inlineCSSPlugin],
    write: true,
  });

  console.log('✅ Build completed: dist/widget.js');

  // Copy to edge function assets directory
  const assetsDir = resolve(__dirname, '../supabase/functions/widget-loader/assets');
  mkdirSync(assetsDir, { recursive: true });
  copyFileSync(resolve(__dirname, 'dist/widget.js'), resolve(assetsDir, 'widget.js'));
  console.log('📁 Copied widget.js to supabase/functions/widget-loader/assets/');

  // Copy to storage seed dir so `supabase start`/`db reset` semeia o bucket `ativos`.
  const seedDir = resolve(__dirname, '../supabase/seed/ativos');
  mkdirSync(seedDir, { recursive: true });
  copyFileSync(resolve(__dirname, 'dist/widget.js'), resolve(seedDir, 'widget.js'));
  console.log('📁 Copied widget.js to supabase/seed/ativos/ (bucket seed)');

  console.log('');
  console.log('🚀 Pronto! Se a stack já estiver rodando, re-semeie o Storage com:');
  console.log('   node ../scripts/upload-widget.mjs   (ou ./build-widget.ps1 / .sh)');
}

build().catch(err => {
  console.error('❌ Build failed:', err);
  process.exit(1);
});

