import { CONFIG } from './config';

export interface DarcyAccessCheck {
    allowed: boolean;
    reason: string;
    message?: string;
}

export interface CourseStudent {
    id: number;
    fullname: string;
    email: string | null;
}

export interface CourseControls {
    is_enabled: boolean;
    is_visible: boolean;
    blocked_student_ids: number[];
    scheduled_block_start: string | null;
    scheduled_block_end: string | null;
    scheduled_block_reason: string | null;
}

export interface TeacherCourseConfig {
    courseId: number;
    courseName: string;
    courseShortname: string;
    students: CourseStudent[];
    controls: CourseControls;
}

const API_BASE = CONFIG.SUPABASE_URL + '/functions/v1/darcy-controls';

// Cache local para evitar chamadas repetidas na mesma sessão
const _roleCache = new Map<string, 'teacher' | 'student'>();

/** Verifica server-side se o userId é professor no courseId via darcy-controls */
export async function checkUserRoleInCourse(
    userId: string,
    courseId: string
): Promise<'teacher' | 'student'> {
    const key = `${userId}:${courseId}`;
    if (_roleCache.has(key)) return _roleCache.get(key)!;

    try {
        const params = new URLSearchParams({ action: 'check-role', userId, courseId });
        const res = await fetch(`${API_BASE}?${params}`, {
            headers: {
                'apikey': CONFIG.SUPABASE_ANON_KEY,
                'Authorization': `Bearer ${CONFIG.SUPABASE_ANON_KEY}`,
            },
        });
        if (!res.ok) return 'student';
        const data = await res.json();
        const role: 'teacher' | 'student' = data.role === 'teacher' ? 'teacher' : 'student';
        _roleCache.set(key, role);
        return role;
    } catch (e) {
        console.warn('[DARCY-CONTROLS] Role check error:', e);
        return 'student';
    }
}

/** Checa se o Darcy está permitido para o aluno no curso */
export async function checkDarcyAccess(courseId: string | null, studentId: string | null): Promise<DarcyAccessCheck> {
    if (!courseId) return { allowed: true, reason: 'no_course_context' };
    try {
        const params = new URLSearchParams({ action: 'check', courseId });
        if (studentId) params.set('studentId', studentId);
        const res = await fetch(`${API_BASE}?${params}`, {
            headers: {
                'apikey': CONFIG.SUPABASE_ANON_KEY,
                'Authorization': `Bearer ${CONFIG.SUPABASE_ANON_KEY}`,
            },
        });
        if (!res.ok) return { allowed: true, reason: 'api_error' };
        return await res.json();
    } catch (e) {
        console.warn('[DARCY-CONTROLS] Check access error:', e);
        return { allowed: true, reason: 'network_error' };
    }
}

/** Busca cursos do professor + configs + alunos */
export async function getTeacherCourseControls(teacherId: string): Promise<TeacherCourseConfig[]> {
    try {
        const params = new URLSearchParams({ action: 'teacher-config', teacherId });
        const res = await fetch(`${API_BASE}?${params}`, {
            headers: {
                'apikey': CONFIG.SUPABASE_ANON_KEY,
                'Authorization': `Bearer ${CONFIG.SUPABASE_ANON_KEY}`,
            },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        return data.courses || [];
    } catch (e) {
        console.error('[DARCY-CONTROLS] Get teacher config error:', e);
        return [];
    }
}

/** Atualiza configurações de um curso */
export async function updateCourseControl(
    teacherId: string,
    courseId: number,
    settings: Partial<CourseControls>
): Promise<{ success: boolean; error?: string }> {
    try {
        const res = await fetch(API_BASE, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'apikey': CONFIG.SUPABASE_ANON_KEY,
                'Authorization': `Bearer ${CONFIG.SUPABASE_ANON_KEY}`,
            },
            body: JSON.stringify({ teacherId, courseId, settings }),
        });
        const data = await res.json();
        if (!res.ok) return { success: false, error: data.error || 'Unknown error' };
        return { success: true };
    } catch (e) {
        console.error('[DARCY-CONTROLS] Update error:', e);
        return { success: false, error: 'Network error' };
    }
}

