let corsHeaders: Record<string, string> = getCorsHeaders();

const MOODLE_URL = Deno.env.get('MOODLE_URL') || '';
const MOODLE_TOKEN = Deno.env.get('MOODLE_TOKEN') || '';

/**
 * Prova de identidade server-side para os endpoints do painel de professor.
 * Compara o header `x-teacher-panel-secret` (ou Authorization: Bearer <secret>)
 * com TEACHER_PANEL_SECRET do env, em tempo constante. Retorna true se valido.
 */
function hasTeacherPanelSecret(req: Request): boolean {
    const expected = Deno.env.get('TEACHER_PANEL_SECRET') || '';
    // Sem segredo configurado => painel fechado (fail-closed). Nunca libera.
    if (!expected) return false;

    let provided = req.headers.get('x-teacher-panel-secret') || '';
    if (!provided) {
        // Aceita tambem Authorization: Bearer <secret> como alternativa.
        const auth = req.headers.get('authorization') || '';
        const m = auth.match(/^Bearer\s+(.+)$/i);
        if (m) provided = m[1].trim();
    }
    if (!provided) return false;
    return timingSafeEqual(provided, expected);
}

/** Comparacao de strings em tempo constante (evita timing oracle no segredo). */
function timingSafeEqual(a: string, b: string): boolean {
    const enc = new TextEncoder();
    const ab = enc.encode(a);
    const bb = enc.encode(b);
    if (ab.length !== bb.length) return false;
    let diff = 0;
    for (let i = 0; i < ab.length; i++) diff |= ab[i] ^ bb[i];
    return diff === 0;
}

function unauthorized(): Response {
    return new Response(JSON.stringify({ error: 'Unauthorized' }), {
        status: 401,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
}

