  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

// Cache-bust: increment version when widget changes
const WIDGET_VERSION = '20260526-v27-voice-continuity';
// LOCAL/self-hosted: busca o widget.js do Storage via a URL INTERNA do Supabase
// (SUPABASE_URL é injetada automaticamente no runtime das edge functions). Funciona
// igual no cloud e no local sem hardcode de projeto — é fetch server->storage.
const SUPABASE_URL = Deno.env.get('SUPABASE_URL') ?? 'http://127.0.0.1:54321';
const WIDGET_URL = `${SUPABASE_URL}/storage/v1/object/public/ativos/widget.js?v=${WIDGET_VERSION}`;

let cachedWidget: string | null = null;
let cacheTime: number = 0;
const CACHE_DURATION = 2 * 60 * 1000; // 2 minutes server cache

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const now = Date.now();

    if (!cachedWidget || (now - cacheTime) > CACHE_DURATION) {
      const response = await fetch(WIDGET_URL);
      if (!response.ok) {
        throw new Error(`Failed to fetch widget: ${response.status}`);
      }
      cachedWidget = await response.text();
      cacheTime = now;
    }

    return new Response(cachedWidget, {
      headers: {
        ...corsHeaders,
        'Content-Type': 'text/javascript; charset=utf-8',
        'Cache-Control': 'public, max-age=120', // 2 min browser cache
        'ETag': `"${WIDGET_VERSION}"`,
      },
    });
  } catch (error) {
    console.error('[widget-loader] Error:', error);
    return new Response('', {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'text/javascript' },
    });
  }
});

